// ---- helpers -------------------------------------------------

const roundUp100 = (n) => Math.ceil((n || 0) / 100) * 100;
const fmt = (n) =>
  (n || 0).toLocaleString("lo-LA", { maximumFractionDigits: 2 });

const emptyItem = () => ({
  id: crypto.randomUUID(),
  name: "",
  qty: "",
  unit: "ກລ",
  hsCode: "",
  unitPrice: "",
  grossWeight: "",
  netWeight: "",
  dutyRate: "5",
  exciseRate: "0",
  vatRate: "10",
  otherRate: "0",
});

const makeSheet = (name) => ({
  id: crypto.randomUUID(),
  name,
  plate: "",
  globalRate: "22703",
  items: [emptyItem()],
});

function computeItem(it, globalRate) {
  const qty = parseFloat(it.qty) || 0;
  const unitPrice = parseFloat(it.unitPrice) || 0;
  const usd = qty * unitPrice;
  const rate = parseFloat(globalRate) || 0;
  const dutyRate = (parseFloat(it.dutyRate) || 0) / 100;
  const exciseRate = (parseFloat(it.exciseRate) || 0) / 100;
  const vatRate = (parseFloat(it.vatRate) || 0) / 100;
  const otherRate = (parseFloat(it.otherRate) || 0) / 100;

  const customsValue = usd * rate;
  const duty = roundUp100(customsValue * dutyRate);
  const exciseBase = customsValue + duty;
  const excise = roundUp100(exciseBase * exciseRate);
  const vatBase = exciseBase + excise;
  const vat = roundUp100(vatBase * vatRate);
  const otherBase = vatBase + vat;
  const other = roundUp100(otherBase * otherRate);
  const totalTax = duty + excise + vat + other;

  return { usd, customsValue, duty, exciseBase, excise, vatBase, vat, otherBase, other, totalTax };
}

// ---- keyboard: move to next input on Enter ----------------------

function focusNextField(e) {
  if (e.key !== "Enter") return;
  e.preventDefault();
  const focusable = Array.from(
    document.querySelectorAll('input:not([disabled]):not([readonly])')
  );
  const idx = focusable.indexOf(e.target);
  if (idx > -1 && idx < focusable.length - 1) {
    const next = focusable[idx + 1];
    next.focus();
    if (next.select) next.select();
  } else {
    e.target.blur();
  }
}

// ---- field ----------------------------------------------------

function Field({ label, value, onChange, suffix, type = "text", placeholder }) {
  return (
    <label className="block">
      <span className="block text-[11px] tracking-wide uppercase text-stone-500 mb-1">
        {label}
      </span>
      <div className="flex items-center rounded-md border border-stone-300 bg-white focus-within:border-[#8a6d3b] focus-within:ring-1 focus-within:ring-[#8a6d3b] transition-colors">
        <input
          type={type}
          inputMode={type === "number" ? "decimal" : "text"}
          value={value}
          placeholder={placeholder}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={focusNextField}
          onWheel={(e) => type === "number" && e.target.blur()}
          className="w-full bg-transparent px-3 py-2 text-[15px] text-stone-800 outline-none placeholder:text-stone-400 no-spinner"
        />
        {suffix && (
          <span className="pr-3 text-[12px] text-stone-400 whitespace-nowrap">{suffix}</span>
        )}
      </div>
    </label>
  );
}

// ---- HS code search / autocomplete field -----------------------

function HsSearchField({ item, onPick }) {
  const [query, setQuery] = useState(item.name || "");
  const [open, setOpen] = useState(false);
  const boxRef = useRef(null);

  useEffect(() => setQuery(item.name || ""), [item.id]);

  useEffect(() => {
    function onClickOutside(e) {
      if (boxRef.current && !boxRef.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", onClickOutside);
    document.addEventListener("touchstart", onClickOutside);
    return () => {
      document.removeEventListener("mousedown", onClickOutside);
      document.removeEventListener("touchstart", onClickOutside);
    };
  }, []);

  const LEADING_VOWELS = ["ເ", "ແ", "ໂ", "ໃ", "ໄ"];
  const matchesName = (n, q) => {
    const nl = n.toLowerCase();
    if (nl.startsWith(q)) return true;
    // words like "ໄຂ່" start with a leading vowel before the consonant;
    // treat them as matching a search for the consonant itself (e.g. "ຂ")
    if (q && LEADING_VOWELS.includes(nl[0]) && nl.slice(1).startsWith(q)) return true;
    return false;
  };

  const matches = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return [];
    return HS_DATA.filter(
      (d) => matchesName(d.n, q) || d.c.toLowerCase().startsWith(q)
    );
  }, [query]);

  const pick = (d) => {
    setQuery(d.n);
    setOpen(false);
    onPick(d);
  };

  return (
    <div className="relative" ref={boxRef}>
      <span className="block text-[11px] tracking-wide uppercase text-stone-500 mb-1">
        ຊື່ສິນຄ້າ / ຄົ້ນຫາ HS Code
      </span>
      <div className="flex items-center rounded-md border border-stone-300 bg-white focus-within:border-[#8a6d3b] focus-within:ring-1 focus-within:ring-[#8a6d3b] transition-colors">
        <Search size={14} className="ml-3 text-stone-400 shrink-0" />
        <input
          type="text"
          value={query}
          placeholder="ພິມຊື່ສິນຄ້າ ຫຼື ລະຫັດ HS ເພື່ອຄົ້ນຫາ..."
          onChange={(e) => {
            setQuery(e.target.value);
            onPick({ n: e.target.value }, true);
            setOpen(true);
          }}
          onFocus={() => setOpen(true)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              if (open && matches.length > 0) {
                pick(matches[0]);
              } else {
                focusNextField(e);
              }
            }
          }}
          className="w-full bg-transparent px-2.5 py-2 text-[15px] text-stone-800 outline-none placeholder:text-stone-400"
        />
      </div>

      {open && matches.length > 0 && (
        <div className="absolute z-20 mt-1 w-full max-h-64 overflow-y-auto rounded-lg border border-stone-200 bg-white shadow-lg">
          {matches.map((d, i) => (
            <button
              key={d.c + i}
              onClick={() => pick(d)}
              className="w-full text-left px-3 py-2 hover:bg-[#faf7f0] border-b border-stone-100 last:border-b-0"
            >
              <div className="text-[13px] text-stone-800 leading-snug">{d.n}</div>
              <div className="text-[11px] text-stone-400 mt-0.5">
                {d.c} · {d.u} · ອ້າງອີງ ${d.p} · ພາສີ {d.d}%
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

